import io.horchestra.pack.sdk.PackSdk;
import io.horchestra.pack.sdk.Rule;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Stream;

/**
 * The artifacts of the openbao example, generated by the Java SDK, are the ones the Go example generates, byte for
 * byte (examples/openbao/golden, written by {@code go test ./examples/openbao/go}). From examples/openbao/java:
 *
 * <pre>
 * javac --release 21 -d out $(find ../../../sdk/java/src/main -name '*.java') ../../postgres/java/Postgres.java OpenBao.java OpenBaoTest.java
 * java -cp out OpenBaoTest
 * </pre>
 */
public class OpenBaoTest {
    private static final Path GOLDEN = Path.of("../golden");

    static List<String> tree(Path dir) throws IOException {
        try (Stream<Path> s = Files.walk(dir)) {
            List<String> out = new ArrayList<>(s.filter(Files::isRegularFile).map(p -> dir.relativize(p).toString()).toList());
            out.sort(Comparator.naturalOrder());
            return out;
        }
    }

    public static void main(String[] args) throws IOException {
        // the postgres pack's content/ is next to its source
        System.setProperty("pack.dir", "../../postgres/java");
        Path out = Files.createTempDirectory("openbao");
        PackSdk.generate(out, new OpenBao());
        int failed = 0;

        // the CEL the pack speaks: the declaration in Java is the one the Go render evaluates
        OpenBao bao = new OpenBao();
        Map<String, String> formulas = bao.packCompute();
        if (!formulas.keySet().equals(Set.of("/openbao/storage"))) {
            System.err.println("FAIL: formulas = " + formulas.keySet());
            failed++;
        } else {
            String expr = formulas.get("/openbao/storage");
            for (String want : List.of("has(pack.values.postgres)", "'postgresql'", "connection_url", "${secret:",
                    "pack.keys.postgres.instances[0]", "ports.pg", "pack.values.postgres.database")) {
                if (!expr.contains(want)) {
                    System.err.println("FAIL: the formula misses " + want + ": " + expr);
                    failed++;
                }
            }
        }
        Map<String, List<Rule>> rules = bao.packRules();
        if (!rules.keySet().equals(Set.of("/openbao/storage")) || rules.get("/openbao/storage").size() != 1) {
            System.err.println("FAIL: rules = " + rules.keySet());
            failed++;
        } else {
            Rule rule = rules.get("/openbao/storage").get(0);
            if (!rule.rule.equals("!has(pack.values.postgres) || !has(values.openbao.storage) || size(values.openbao.storage) == 0")) {
                System.err.println("FAIL: rule = " + rule.rule);
                failed++;
            }
            if (rule.message.isEmpty()) {
                System.err.println("FAIL: a violation tells the operator why");
                failed++;
            }
            if (!rule.phases.isEmpty()) {
                System.err.println("FAIL: an unphased rule is the operator's document's (preMutate): " + rule.phases);
                failed++;
            }
        }

        if (!tree(GOLDEN).equals(tree(out))) {
            System.err.println("FAIL: files: golden " + tree(GOLDEN) + ", got " + tree(out));
            failed++;
        }
        for (String rel : tree(GOLDEN)) {
            if (Files.exists(out.resolve(rel)) && !new String(Files.readAllBytes(GOLDEN.resolve(rel))).equals(new String(Files.readAllBytes(out.resolve(rel))))) {
                System.err.println("FAIL: " + rel + " differs from the Go example's");
                failed++;
            }
        }
        if (failed > 0) System.exit(1);
        System.out.println("ok");
    }
}
